/** Adobe-Japan1 の CID を Unicode 文字へ。対応が無ければ null */
export function cidToUnicode(cid: number): string | null {
  const m = MULTI[cid]
  if (m) return m
  if (cid < 0 || cid >= TABLE.length) return null
  const c = TABLE[cid]
  return c === '\u0000' ? null : c
}
